import json
import requests
from datetime import datetime
from zai import ZhipuAiClient

class FunctionAgent:
    def __init__(self, api_key):
        self.client = ZhipuAiClient(api_key=api_key)
        self.tools = self._define_tools()

    def _define_tools(self):
        return [
            {
                "type": "function",
                "function": {
                    "name": "get_current_time",
                    "description": "获取当前时间",
                    "parameters": {
                        "type": "object",
                        "properties": {},
                        "required": []
                    }
                }
            },
            {
                "type": "function",
                "function": {
                    "name": "calculate",
                    "description": "执行数学计算",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "expression": {
                                "type": "string",
                                "description": "数学表达式，如：2+3*4"
                            }
                        },
                        "required": ["expression"]
                    }
                }
            },
            {
                "type": "function",
                "function": {
                    "name": "search_web",
                    "description": "搜索网络信息",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "string",
                                "description": "搜索关键词"
                            }
                        },
                        "required": ["query"]
                    }
                }
            }
        ]

    def get_current_time(self):
        """获取当前时间"""
        return {
            "current_time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "timezone": "Asia/Shanghai"
        }

    def calculate(self, expression: str):
        """安全的数学计算"""
        try:
            # 简单的安全检查
            allowed_chars = set('0123456789+-*/().')
            if not all(c in allowed_chars or c.isspace() for c in expression):
                return {"error": "表达式包含不允许的字符"}

            result = eval(expression)
            return {
                "expression": expression,
                "result": result
            }
        except Exception as e:
            return {"error": f"计算错误: {str(e)}"}

    def search_web(self, query: str):
        """模拟网络搜索"""
        # 这里应该调用真实的搜索 API
        return {
            "query": query,
            "results": [
                {"title": f"关于{query}的搜索结果1", "url": "https://example1.com"},
                {"title": f"关于{query}的搜索结果2", "url": "https://example2.com"}
            ]
        }

    def execute_function(self, function_name: str, arguments: dict):
        """执行函数调用"""
        if function_name == "get_current_time":
            return self.get_current_time()
        elif function_name == "calculate":
            return self.calculate(arguments.get("expression", ""))
        elif function_name == "search_web":
            return self.search_web(arguments.get("query", ""))
        else:
            return {"error": f"未知函数: {function_name}"}

    def chat(self, user_message: str):
        """处理用户消息"""
        messages = [{"role": "user", "content": user_message}]

        response = self.client.chat.completions.create(
            model="glm-4.7",
            messages=messages,
            tools=self.tools,
            tool_choice="auto"
        )

        message = response.choices[0].message
        messages.append(message.model_dump())

        # 处理函数调用
        if message.tool_calls:
            for tool_call in message.tool_calls:
                function_name = tool_call.function.name
                arguments = json.loads(tool_call.function.arguments)

                # 执行函数
                result = self.execute_function(function_name, arguments)

                # 添加函数结果
                messages.append({
                    "role": "tool",
                    "content": json.dumps(result, ensure_ascii=False),
                    "tool_call_id": tool_call.id
                })

            # 获取最终回答
            final_response = self.client.chat.completions.create(
                model="glm-4.7",
                messages=messages,
                tools=self.tools
            )

            return final_response.choices[0].message.content
        else:
            return message.content

# 使用示例
agent = FunctionAgent("your_api_key")

# 测试不同类型的请求
print(agent.chat("现在几点了？"))
print(agent.chat("帮我计算 15 * 23 + 7"))
print(agent.chat("搜索一下人工智能的最新发展"))
